<template><main class="hh-page surgical-unit"><section class="surgical-hero"><div><span>GESTIÓN QUIRÚRGICA</span><h1>Unidad quirúrgica</h1><p>Supervise la operación diaria, ocupación y programación de los quirófanos.</p></div><div><router-link to="/unidad-quirurgica/agenda" class="btn btn-outline-light"><i class="ph ph-calendar me-1"></i>Agenda</router-link><router-link to="/unidad-quirurgica/programar" class="btn btn-light text-primary"><i class="ph ph-plus me-1"></i>Programar cirugía</router-link></div></section><div v-if="error" class="alert alert-danger mt-3">{{error}}</div><div class="metrics mt-4"><article><span class="blue"><i class="ph ph-door-open"></i></span><div><small>Quirófanos con agenda</small><strong>{{groups.length}}</strong></div></article><article><span class="green"><i class="ph ph-activity"></i></span><div><small>Cirugías activas</small><strong>{{activeCount}}</strong></div></article><article><span class="amber"><i class="ph ph-clock"></i></span><div><small>Programadas hoy</small><strong>{{scheduledCount}}</strong></div></article><article><span class="gray"><i class="ph ph-check-circle"></i></span><div><small>Finalizadas</small><strong>{{finishedCount}}</strong></div></article></div><section class="daily-board mt-4"><header><div><small>RESUMEN DE HOY</small><h2>Actividad por quirófano</h2><p>{{todayLabel}}</p></div><div><router-link to="/unidad-quirurgica/historial" class="btn btn-outline-primary">Historial</router-link><router-link to="/unidad-quirurgica/parametrizacion" class="btn btn-outline-primary"><i class="ph ph-gear me-1"></i>Parametrización</router-link><button class="btn btn-primary" :disabled="loading" @click="load"><i class="ph ph-arrows-clockwise"></i></button></div></header><div v-if="loading" class="loading"><span class="spinner-border text-primary"></span></div><div v-else-if="!groups.length" class="empty"><i class="ph ph-calendar-x"></i><h3>Sin cirugías para hoy</h3><p>Los quirófanos no tienen procedimientos programados.</p></div><div v-else class="room-grid"><article v-for="group in groups" :key="group.id"><header><span><i class="ph ph-door-open"></i></span><div><small>QUIRÓFANO</small><h3>{{group.name}}</h3></div><em>{{group.surgeries.length}} cirugías</em></header><div class="surgery-list"><router-link v-for="surgery in group.surgeries" :key="surgery.id_procedimiento||surgery.id" :to="`/unidad-quirurgica/cirugias/${surgery.id_procedimiento||surgery.id}`"><time>{{String(surgery.hora_inicio).slice(0,5)}}</time><div><strong>{{surgery.procedimiento||'Procedimiento quirúrgico'}}</strong><small>{{surgery.paciente}} · {{surgery.cirujano}}</small></div><span :class="statusClass(surgery)">{{surgery.estado_procedimiento||surgery.estado_programacion}}</span></router-link></div></article></div></section></main></template>
<script setup>import{computed,onMounted,ref}from'vue';import{obtenerMensajeError}from'@/services/api';import{consultarResumenQuirofanos}from'@/services/unidadQuirurgica';const rows=ref([]),loading=ref(false),error=ref(''),array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:[],groups=computed(()=>{const map=new Map;rows.value.forEach(x=>{const id=x.id_quirofano;if(!map.has(id))map.set(id,{id,name:x.nombre||x.nombre_quirofano||`Quirófano ${id}`,surgeries:[]});map.get(id).surgeries.push(x)});return[...map.values()].map(g=>({...g,surgeries:g.surgeries.sort((a,b)=>String(a.hora_inicio).localeCompare(String(b.hora_inicio)))}))}),activeCount=computed(()=>rows.value.filter(x=>/activa|proceso/i.test(`${x.estado_programacion} ${x.estado_procedimiento}`)).length),scheduledCount=computed(()=>rows.value.filter(x=>/programada|pendiente/i.test(`${x.estado_programacion} ${x.estado_procedimiento}`)).length),finishedCount=computed(()=>rows.value.filter(x=>/finalizada|finalizado/i.test(`${x.estado_programacion} ${x.estado_procedimiento}`)).length),todayLabel=new Intl.DateTimeFormat('es-CO',{dateStyle:'full'}).format(new Date()),statusClass=x=>/activa|proceso/i.test(`${x.estado_programacion} ${x.estado_procedimiento}`)?'active':/final/i.test(`${x.estado_programacion} ${x.estado_procedimiento}`)?'finished':'scheduled';async function load(){loading.value=true;error.value='';try{rows.value=array(await consultarResumenQuirofanos())}catch(e){error.value=obtenerMensajeError(e)}finally{loading.value=false}}onMounted(load)</script>
<style scoped>.surgical-hero{display:flex;align-items:center;justify-content:space-between;padding:1.5rem;border-radius:1rem;background:linear-gradient(120deg,#124b76,#1187ac);color:#fff;box-shadow:0 14px 34px rgba(15,75,117,.2)}.surgical-hero span,.daily-board>header small{font-size:.68rem;font-weight:800;letter-spacing:.08em}.surgical-hero h1{margin:.2rem 0;font-size:1.65rem}.surgical-hero p{margin:0;opacity:.82}.surgical-hero>div:last-child,.daily-board>header>div:last-child{display:flex;gap:.5rem}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:.8rem}.metrics article{display:flex;align-items:center;gap:.7rem;padding:1rem;border:1px solid #dfe7ee;border-radius:.85rem;background:#fff}.metrics article>span{display:grid;place-items:center;width:43px;height:43px;border-radius:12px;font-size:1.15rem}.blue{background:#e8f4fc;color:#247bad}.green{background:#e8f8f0;color:#26845e}.amber{background:#fff3df;color:#bd741c}.gray{background:#eef1f4;color:#687686}.metrics small,.metrics strong{display:block}.metrics small{color:#7d8b9a}.metrics strong{font-size:1.35rem}.daily-board{overflow:hidden;border:1px solid #dfe7ee;border-radius:1rem;background:#fff;box-shadow:0 9px 28px rgba(25,63,95,.06)}.daily-board>header{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.2rem;border-bottom:1px solid #e3e9ef;background:#fbfcfe}.daily-board h2{margin:.1rem 0;font-size:1.1rem}.daily-board header p{margin:0;color:#748396}.loading,.empty{text-align:center;padding:4rem;color:#718096}.empty i{font-size:2.8rem;color:#abc1d0}.empty h3{margin:.6rem 0 .2rem;font-size:1rem}.room-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.8rem;padding:1rem}.room-grid>article{overflow:hidden;border:1px solid #e0e7ed;border-radius:.8rem}.room-grid article>header{display:flex;align-items:center;gap:.65rem;padding:.8rem;border-bottom:1px solid #e5ebef}.room-grid header>span{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:#e8f4fc;color:var(--bs-primary)}.room-grid header>div{flex:1}.room-grid header small{color:#8290a0}.room-grid h3{margin:.1rem 0;font-size:.85rem}.room-grid header em{font-size:.68rem;font-style:normal}.surgery-list{display:grid}.surgery-list>a{display:flex;align-items:center;gap:.6rem;padding:.7rem .8rem;border-bottom:1px solid #edf0f3;color:#415165}.surgery-list time{font-weight:800}.surgery-list div{min-width:0;flex:1}.surgery-list strong,.surgery-list small{display:block}.surgery-list strong{font-size:.77rem}.surgery-list small{color:#7d8b9a}.surgery-list>a>span{padding:.25rem .45rem;border-radius:20px;font-size:.64rem}.scheduled{background:#e8f4fc;color:#247bad}.active{background:#e8f8f0;color:#26845e}.finished{background:#eef1f4;color:#687686}@media(max-width:900px){.metrics,.room-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.surgical-hero,.daily-board>header{align-items:flex-start;flex-direction:column;gap:1rem}.metrics,.room-grid{grid-template-columns:1fr}}</style>
